/bin/bash -lc "python - <<'PY'
import numpy as np
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.svm import SVC
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score
from sklearn.model_selection import StratifiedKFold, cross_val_score

tr=np.load('/app/data/train_labeled.npz',allow_pickle=False)
va=np.load('/app/data/val_labeled.npz',allow_pickle=False)
Xtr=tr['spikes']; ytr=tr['y']
Xva=va['spikes']; yva=va['y']

# check label consistency with movie_time_s
for name,d in [('train',tr),('val',va)]:
    y=d['y']; mt=d['movie_time_s']
    y_from_mt=(mt-3).astype(int)
    print(name,'label mismatch count',np.sum(y"'!=y_from_mt))

# features

def feat_flat(X):
    return X.reshape(len(X),-1)

def feat_sum_time(X):
    return X.sum(axis=2)

def feat_sum_units(X):
    return X.sum(axis=1)

def feat_combo(X):
    f1=X.reshape(len(X),-1)
    f2=X.sum(axis=2)
    f3=X.sum(axis=1)
    return np.concatenate([f1,f2,f3],axis=1)

feats={'"'flat':feat_flat,'sum_time':feat_sum_time,'sum_units':feat_sum_units,'combo':feat_combo}
models={
'logreg':Pipeline([('sc',StandardScaler()),('clf',LogisticRegression(max_iter=5000,multi_class='multinomial',C=1.0))]),
'logreg_l2_0.3':Pipeline([('sc',StandardScaler()),('clf',LogisticRegression(max_iter=5000,multi_class='multinomial',C=0.3))]),
'svm_rbf':Pipeline([('sc',StandardScaler()),('clf',SVC(C=3,gamma='scale'))]),
'rf':RandomForestClassifier(n_estimators=500,random_state=0)
}

best=None
for fk,ff in feats.items():
    Xtrf=ff(Xtr); Xvaf=ff(Xva)
    for mk,m in models.items():
        m.fit(Xtrf,ytr)
        pv=m.predict(Xvaf)
        acc=accuracy_score(yva,pv)
        cv=cross_val_score(m,np.vstack([Xtrf,Xvaf]),np.hstack([ytr,yva]),cv=StratifiedKFold(n_splits=5,shuffle=True,random_state=0)).mean()
        print(f'{fk:9s} {mk:14s} val={acc:.3f} cv_all={cv:.3f}')
        if best is None or acc>best[0] or (acc==best[0] and cv>best[1]):
            best=(acc,cv,fk,mk,m)

print('BEST',best[:4])
PY"

